class Solution {
    public void sortColors(int[] nums) {
        int lo = 0, i = 0, hi = nums.length - 1;   // [0,lo) 是 0，[lo,i) 是 1，(hi,end] 是 2
        while (i <= hi) {
            if (nums[i] == 0) {
                swap(nums, lo, i);
                lo++;
                i++;
            } else if (nums[i] == 2) {
                swap(nums, i, hi);
                hi--;                               // 换过来的数还没看过，i 不动
            } else {
                i++;
            }
        }
    }

    private void swap(int[] nums, int a, int b) {
        int t = nums[a];
        nums[a] = nums[b];
        nums[b] = t;
    }
}

